-- Peelr September 2026 questions: FRIENDS
-- Theme: New Beginnings, a fresh start. New routines, new goals, the version of you stepping into fall.
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
-- Layer 1: playful, light, group energy
('friends', 1, 'What is the default plan for this group when nobody can decide what to do?', '¿Cuál es el plan de siempre de este grupo cuando nadie se decide?'),
('friends', 1, 'If you started one new hobby this fall, what would actually stick?', 'Si empezaras un pasatiempo nuevo este otoño, ¿cuál se te quedaría de verdad?'),
('friends', 1, 'What is one thing you want to try for the first time this season?', '¿Qué quieres probar por primera vez esta temporada?'),
('friends', 1, 'Who in this group is most likely to actually keep a September resolution?', '¿Quién de este grupo es más capaz de cumplir un propósito de septiembre?'),
('friends', 1, 'What small thing instantly puts you in a good mood?', '¿Qué cosa pequeña te pone de buen humor al instante?'),
('friends', 1, 'What are you most excited to start this month?', '¿Qué es lo que más ganas tienes de empezar este mes?'),
('friends', 1, 'Which of us would survive the longest without a phone?', '¿Quién de nosotros aguantaría más tiempo sin celular?'),
('friends', 1, 'What is a skill you wish you had learned by now?', '¿Qué habilidad te gustaría ya haber aprendido?'),
('friends', 1, 'Who in this group gives the most convincing fake enthusiasm?', '¿Quién de este grupo finge entusiasmo de forma más creíble?'),
('friends', 1, 'What is the most useless talent you are proud of?', '¿Cuál es el talento más inútil del que estás orgulloso?'),
('friends', 1, 'What is a routine you are trying to build this fall?', '¿Qué rutina estás tratando de construir este otoño?'),
('friends', 1, 'If this group had a theme song, what would it be?', 'Si este grupo tuviera una canción propia, ¿cuál sería?'),
('friends', 1, 'What is something small that made you happy this week?', '¿Qué cosa pequeña te hizo feliz esta semana?'),
('friends', 1, 'What are you looking forward to now that summer is over?', '¿Qué esperas con ganas ahora que terminó el verano?'),
('friends', 1, 'What is a memory with this group you did not expect to matter this much?', '¿Qué recuerdo con este grupo te importó más de lo que esperabas?'),
('friends', 1, 'What is something you have gotten better at without even trying?', '¿En qué has mejorado sin siquiera intentarlo?'),
('friends', 1, 'What habit are you trying to leave behind this season?', '¿Qué costumbre estás tratando de dejar atrás esta temporada?'),
('friends', 1, 'What made you laugh the hardest recently?', '¿Qué te hizo reír más fuerte recientemente?'),
('friends', 1, 'What do you think makes this group actually work?', '¿Qué crees que hace que este grupo funcione de verdad?'),
('friends', 1, 'What do you want this next chapter of your life to look like?', '¿Cómo quieres que se vea este próximo capítulo de tu vida?'),
